insert into public.challenges
  (id, track, kind, difficulty, prompt, options, correct_option_id, explanation, court,
   source_name, source_url, approved, coach_review_required)
values
  ('challenger-01', 'challenger', 'court-position', 1, 'The ball marker sits on the line that runs across your half of the court, about halfway between the net and your baseline. What is this line called?', '[{"id":"a","label":"Baseline"},{"id":"b","label":"Service line"},{"id":"c","label":"Center service line"},{"id":"d","label":"Singles sideline"}]'::jsonb, 'b', 'The service line marks the back of the service boxes, about halfway between the net and the baseline. The baseline is the line at the very back of the court.', '{"player":{"x":50,"y":97},"opponent":{"x":50,"y":3},"ball":{"x":50,"y":67.9},"caption":"You stand behind your baseline at the bottom of the court. The ball marker sits in the middle of the line that crosses your half of the court, about halfway between the net and your baseline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-02', 'challenger', 'court-position', 1, 'After a rally shot, you are standing between your service line and your baseline. Why do coaches advise against staying there while your opponent hits?', '[{"id":"a","label":"Deep balls tend to bounce near your feet there, making clean shots hard"},{"id":"b","label":"The rules do not allow you to stand there during a rally"},{"id":"c","label":"You are not allowed to volley from there"},{"id":"d","label":"Lobs can only land in that area"}]'::jsonb, 'a', 'In this middle zone a deep ball often bounces at your feet, so you are forced into a half-volley or a rushed shot. Moving forward to the net or back behind the baseline gives you a clearer ball to hit.', '{"player":{"x":50,"y":81},"opponent":{"x":50,"y":4},"caption":"You are in the middle of your half, between your service line and your baseline. Your opponent is behind the far baseline, about to hit."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-03', 'challenger', 'court-position', 2, 'You just hit a deep crosscourt shot from near your right sideline. Your opponent will hit from behind their baseline on the left side of the diagram and could go anywhere. Where should you recover?', '[{"id":"a","label":"Exactly on the center mark"},{"id":"b","label":"Stay near your right sideline, where you hit from"},{"id":"c","label":"A little right of the center mark, just behind your baseline"},{"id":"d","label":"Forward to the middle of your service line"}]'::jsonb, 'c', 'Your opponent''s sharpest crosscourt angle is wider than their down-the-line option, so the middle of their possible shots is a little to the crosscourt side of the center mark. Exact center is close but leaves that wide angle more open, and staying out wide leaves the down-the-line side open.', '{"player":{"x":76,"y":96},"opponent":{"x":22,"y":6},"recommendedPath":[{"x":76,"y":96},{"x":57,"y":96}],"caption":"You are behind your baseline near the right sideline after hitting crosscourt. Your opponent is behind the far baseline on the left side of the diagram, about to reply."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-04', 'challenger', 'court-position', 2, 'You are rallying from your baseline near the right sideline. Why is a crosscourt shot toward the far left corner usually safer than going down the line?', '[{"id":"a","label":"In singles, crosscourt shots may land in the doubles alley"},{"id":"b","label":"The net is highest in the middle, which stops the ball going long"},{"id":"c","label":"Crosscourt shots always bounce higher"},{"id":"d","label":"It crosses the lower middle of the net and has a longer diagonal court to land in"}]'::jsonb, 'd', 'The net is lowest at the center (0.914 m) and higher at the posts, and the diagonal is longer than the sideline. A crosscourt ball therefore has more room for error both over the net and in length.', '{"player":{"x":78,"y":95},"opponent":{"x":50,"y":5},"recommendedPath":[{"x":78,"y":93},{"x":24,"y":12}],"caption":"You are behind your baseline near the right sideline. Your opponent is in the middle behind the far baseline. A diagonal toward the far left corner passes over the middle of the net."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-05', 'challenger', 'court-position', 3, 'You just hit down the line from near your right sideline, and your opponent will reply from the far right corner. Where should you recover?', '[{"id":"a","label":"Stay near your right sideline"},{"id":"b","label":"Move across to a little left of the center mark, just behind your baseline"},{"id":"c","label":"Go exactly to the center mark and stop"},{"id":"d","label":"Run to the left corner of your baseline"}]'::jsonb, 'b', 'From the far right corner, your opponent''s sharpest crosscourt angle goes toward your left side, so the middle of their options is slightly left of center. Going down the line means a longer recovery run, which is a trade-off of changing direction.', '{"player":{"x":80,"y":96},"opponent":{"x":78,"y":6},"recommendedPath":[{"x":80,"y":96},{"x":43,"y":96}],"caption":"You are behind your baseline near the right sideline after hitting down the line. Your opponent is behind the far baseline near the right side of the diagram, directly up the court from you."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-06', 'challenger', 'court-position', 1, 'In a baseline rally against an opponent who hits deep with medium pace, where is a good default spot to wait between shots?', '[{"id":"a","label":"About a step behind the baseline, near the middle"},{"id":"b","label":"On your service line"},{"id":"c","label":"Two steps inside your baseline"},{"id":"d","label":"Far back, close to the back fence"}]'::jsonb, 'a', 'About a step behind the baseline gives you time against deep balls while still letting you move forward to short ones. Standing much further back buys more time but opens angles and means more running.', '{"player":{"x":50,"y":88},"opponent":{"x":50,"y":3},"caption":"You are near the middle of your half of the court. Your opponent is rallying from behind the far baseline in the middle."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-07', 'challenger', 'court-position', 2, 'You have moved forward to the net to volley. Where is a good default position?', '[{"id":"a","label":"Right against the net, almost touching it"},{"id":"b","label":"On your service line"},{"id":"c","label":"Between your service line and your baseline"},{"id":"d","label":"Roughly halfway between your service line and the net"}]'::jsonb, 'd', 'Halfway between the service line and the net lets you cut off most passing shots while still having time to react and cover a lob. Very close to the net is easy to lob over, and the service line leaves many volleys low at your feet.', '{"player":{"x":50,"y":69},"opponent":{"x":50,"y":4},"caption":"You have just moved forward past your service line toward the net. Your opponent is behind the far baseline in the middle."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-08', 'challenger', 'court-position', 1, 'In a doubles rally (not the serve), the ball lands in the alley between the singles and doubles sidelines on your side. Is it in or out?', '[{"id":"a","label":"Out, because the alley is only used in singles"},{"id":"b","label":"Out, unless the ball touches the singles sideline"},{"id":"c","label":"In, because the alleys are part of the doubles court during rallies"},{"id":"d","label":"Neither: the point is replayed"}]'::jsonb, 'c', 'After the serve, the doubles court runs out to the doubles sidelines and includes both alleys. A ball landing in the alley during a doubles rally is good.', '{"player":{"x":40,"y":90},"opponent":{"x":60,"y":8},"ball":{"x":89,"y":80},"caption":"Doubles rally. You are near your baseline. The ball bounces in the narrow strip along the right edge of your half, outside the singles sideline but inside the outer doubles sideline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-09', 'challenger', 'court-position', 2, 'In doubles, your serve lands in the alley right next to the correct service box. What is the call?', '[{"id":"a","label":"Fault, because the service box ends at the singles sideline"},{"id":"b","label":"Good, because the alleys count in doubles"},{"id":"c","label":"Let, so the serve is replayed"},{"id":"d","label":"Good, but only on a second serve"}]'::jsonb, 'a', 'The service boxes are the same in singles and doubles, and their outer edge is the singles sideline. A serve landing in the alley is a fault, even though the alley is in for the rest of the rally.', '{"player":{"x":58,"y":97},"opponent":{"x":25,"y":4},"ball":{"x":11.5,"y":42},"caption":"You serve from behind your baseline, just right of the center mark. The ball lands on the far side of the net on the left of the diagram, in the narrow alley just outside the left service box."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-10', 'challenger', 'court-position', 2, 'Doubles: your partner serves from the right half of your baseline. As the server''s partner, where do you usually start?', '[{"id":"a","label":"Next to your partner on the baseline"},{"id":"b","label":"In the right service box, directly in front of your partner"},{"id":"c","label":"On the center service line, touching the net"},{"id":"d","label":"In the left service box, roughly halfway between the net and the service line"}]'::jsonb, 'd', 'The traditional ''one up, one back'' start puts the server''s partner at the net on the opposite side from the server, guarding the alley and ready to intercept. Some teams choose other formations, such as both back, but this is the standard starting point.', null, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-100', 'challenger', 'court-position', 3, 'Positioning rep 90: on the near net, you are chasing a drop shot. Where should you move by default?', '[{"id":"a","label":"Wait at baseline"},{"id":"b","label":"Run through without control"},{"id":"c","label":"Turn away"},{"id":"d","label":"Sprint forward, then slow down before contact"}]'::jsonb, 'd', 'A drop shot requires speed first and controlled last steps before contact.', '{"player":{"x":45,"y":88},"opponent":{"x":58,"y":12},"ball":{"x":47,"y":55},"recommendedPath":[{"x":45,"y":88},{"x":50,"y":82}],"caption":"Positioning rep 90: you are on the near net while you are chasing a drop shot."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-101', 'challenger', 'court-position', 1, 'Positioning rep 91: on the behind baseline, opponent is deep and central. Where should you move by default?', '[{"id":"a","label":"Wait a step behind the baseline near the middle"},{"id":"b","label":"Stand inside the service line"},{"id":"c","label":"Recover to a doubles alley"},{"id":"d","label":"Move all the way to net"}]'::jsonb, 'a', 'A deep central ball calls for a balanced recovery near the middle and slightly behind the baseline.', '{"player":{"x":52,"y":88},"opponent":{"x":50,"y":8},"ball":{"x":52,"y":80},"recommendedPath":[{"x":52,"y":88},{"x":50,"y":82}],"caption":"Positioning rep 91: you are on the behind baseline while opponent is deep and central."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-102', 'challenger', 'court-position', 2, 'Positioning rep 92: on the behind baseline, you are pulled wide outside the singles sideline. Where should you move by default?', '[{"id":"a","label":"Stay outside the alley"},{"id":"b","label":"Recover diagonally toward the center of likely replies"},{"id":"c","label":"Run blindly to net"},{"id":"d","label":"Stand still"}]'::jsonb, 'b', 'After being pulled wide, recover toward the middle of the opponent’s realistic angles.', '{"player":{"x":52,"y":78},"opponent":{"x":50,"y":12},"ball":{"x":52,"y":72},"recommendedPath":[{"x":52,"y":78},{"x":50,"y":82}],"caption":"Positioning rep 92: you are on the behind baseline while you are pulled wide outside the singles sideline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-103', 'challenger', 'court-position', 1, 'Positioning rep 93: on the behind baseline, you move in for a short ball. Where should you move by default?', '[{"id":"a","label":"Retreat behind the fence"},{"id":"b","label":"Freeze at the baseline"},{"id":"c","label":"Move forward and stay balanced for the next shot"},{"id":"d","label":"Turn away"}]'::jsonb, 'c', 'A short ball invites purposeful forward movement and balanced preparation.', '{"player":{"x":52,"y":62},"opponent":{"x":50,"y":14},"ball":{"x":52,"y":58},"recommendedPath":[{"x":52,"y":62},{"x":50,"y":82}],"caption":"Positioning rep 93: you are on the behind baseline while you move in for a short ball."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-104', 'challenger', 'court-position', 3, 'Positioning rep 94: on the behind baseline, you are at net and the opponent is stretched. Where should you move by default?', '[{"id":"a","label":"Back up behind baseline"},{"id":"b","label":"Stand at one alley only"},{"id":"c","label":"Watch without moving"},{"id":"d","label":"Split step and cover the high-percentage pass"}]'::jsonb, 'd', 'At net, split step and cover the likely passing lane or volley.', '{"player":{"x":52,"y":58},"opponent":{"x":50,"y":18},"ball":{"x":52,"y":24},"recommendedPath":[{"x":52,"y":58},{"x":50,"y":82}],"caption":"Positioning rep 94: you are on the behind baseline while you are at net and the opponent is stretched."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-105', 'challenger', 'court-position', 1, 'Positioning rep 95: on the behind baseline, a high deep ball is landing near your baseline. Where should you move by default?', '[{"id":"a","label":"Give yourself space behind the bounce"},{"id":"b","label":"Crowd the bounce"},{"id":"c","label":"Charge forward early"},{"id":"d","label":"Stand in no-man’s-land"}]'::jsonb, 'a', 'High deep balls require space so you can strike in balance.', '{"player":{"x":52,"y":94},"opponent":{"x":50,"y":9},"ball":{"x":52,"y":90},"recommendedPath":[{"x":52,"y":94},{"x":50,"y":82}],"caption":"Positioning rep 95: you are on the behind baseline while a high deep ball is landing near your baseline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-106', 'challenger', 'court-position', 2, 'Positioning rep 96: on the behind baseline, the opponent is approaching the net. Where should you move by default?', '[{"id":"a","label":"Hit while falling away"},{"id":"b","label":"Set your feet and prepare pass or lob coverage"},{"id":"c","label":"Stop recovering"},{"id":"d","label":"Always drop shot"}]'::jsonb, 'b', 'Balance gives you time to choose a pass or lob against an approaching player.', '{"player":{"x":52,"y":84},"opponent":{"x":50,"y":32},"ball":{"x":52,"y":78},"recommendedPath":[{"x":52,"y":84},{"x":50,"y":82}],"caption":"Positioning rep 96: you are on the behind baseline while the opponent is approaching the net."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-107', 'challenger', 'court-position', 1, 'Positioning rep 97: on the behind baseline, the opponent hits from a corner. Where should you move by default?', '[{"id":"a","label":"Ignore the open court"},{"id":"b","label":"Run behind the fence"},{"id":"c","label":"Shade recovery toward the open attacking lane"},{"id":"d","label":"Stand on the wrong alley"}]'::jsonb, 'c', 'Opponent position changes their angles, so shade toward the space they can attack.', '{"player":{"x":52,"y":83},"opponent":{"x":50,"y":10},"ball":{"x":52,"y":74},"recommendedPath":[{"x":52,"y":83},{"x":50,"y":82}],"caption":"Positioning rep 97: you are on the behind baseline while the opponent hits from a corner."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-108', 'challenger', 'court-position', 3, 'Positioning rep 98: on the behind baseline, you are stuck between baseline and service line. Where should you move by default?', '[{"id":"a","label":"Stay in no-man’s-land"},{"id":"b","label":"Face the side fence"},{"id":"c","label":"Stop moving"},{"id":"d","label":"Commit forward or recover back; do not linger"}]'::jsonb, 'd', 'The middle transition area is awkward, so make a clear positional choice.', '{"player":{"x":52,"y":72},"opponent":{"x":50,"y":12},"ball":{"x":52,"y":64},"recommendedPath":[{"x":52,"y":72},{"x":50,"y":82}],"caption":"Positioning rep 98: you are on the behind baseline while you are stuck between baseline and service line."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-109', 'challenger', 'court-position', 1, 'Positioning rep 99: on the behind baseline, you hit a crosscourt rally ball. Where should you move by default?', '[{"id":"a","label":"Recover slightly toward the crosscourt exchange"},{"id":"b","label":"Run to opposite alley"},{"id":"c","label":"Stand at net post"},{"id":"d","label":"Stay frozen"}]'::jsonb, 'a', 'Crosscourt rallies create natural angles, so recover with a slight shade to that exchange.', '{"player":{"x":52,"y":86},"opponent":{"x":50,"y":10},"ball":{"x":52,"y":76},"recommendedPath":[{"x":52,"y":86},{"x":50,"y":82}],"caption":"Positioning rep 99: you are on the behind baseline while you hit a crosscourt rally ball."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-11', 'challenger', 'court-position', 1, 'Positioning rep 1: on the middle, opponent is deep and central. Where should you move by default?', '[{"id":"a","label":"Stand inside the service line"},{"id":"b","label":"Recover to a doubles alley"},{"id":"c","label":"Wait a step behind the baseline near the middle"},{"id":"d","label":"Move all the way to net"}]'::jsonb, 'c', 'A deep central ball calls for a balanced recovery near the middle and slightly behind the baseline.', '{"player":{"x":50,"y":88},"opponent":{"x":50,"y":8},"ball":{"x":50,"y":80},"recommendedPath":[{"x":50,"y":88},{"x":50,"y":82}],"caption":"Positioning rep 1: you are on the middle while opponent is deep and central."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-110', 'challenger', 'court-position', 2, 'Positioning rep 100: on the behind baseline, you are chasing a drop shot. Where should you move by default?', '[{"id":"a","label":"Wait at baseline"},{"id":"b","label":"Sprint forward, then slow down before contact"},{"id":"c","label":"Run through without control"},{"id":"d","label":"Turn away"}]'::jsonb, 'b', 'A drop shot requires speed first and controlled last steps before contact.', '{"player":{"x":52,"y":88},"opponent":{"x":50,"y":12},"ball":{"x":52,"y":55},"recommendedPath":[{"x":52,"y":88},{"x":50,"y":82}],"caption":"Positioning rep 100: you are on the behind baseline while you are chasing a drop shot."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-111', 'challenger', 'court-position', 1, 'Positioning rep 101: on the middle, opponent is deep and central. Where should you move by default?', '[{"id":"a","label":"Stand inside the service line"},{"id":"b","label":"Recover to a doubles alley"},{"id":"c","label":"Wait a step behind the baseline near the middle"},{"id":"d","label":"Move all the way to net"}]'::jsonb, 'c', 'A deep central ball calls for a balanced recovery near the middle and slightly behind the baseline.', '{"player":{"x":50,"y":88},"opponent":{"x":50,"y":8},"ball":{"x":50,"y":80},"recommendedPath":[{"x":50,"y":88},{"x":50,"y":82}],"caption":"Positioning rep 101: you are on the middle while opponent is deep and central."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-112', 'challenger', 'court-position', 3, 'Positioning rep 102: on the middle, you are pulled wide outside the singles sideline. Where should you move by default?', '[{"id":"a","label":"Stay outside the alley"},{"id":"b","label":"Run blindly to net"},{"id":"c","label":"Stand still"},{"id":"d","label":"Recover diagonally toward the center of likely replies"}]'::jsonb, 'd', 'After being pulled wide, recover toward the middle of the opponent’s realistic angles.', '{"player":{"x":50,"y":78},"opponent":{"x":50,"y":12},"ball":{"x":50,"y":72},"recommendedPath":[{"x":50,"y":78},{"x":50,"y":82}],"caption":"Positioning rep 102: you are on the middle while you are pulled wide outside the singles sideline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-113', 'challenger', 'court-position', 1, 'Positioning rep 103: on the middle, you move in for a short ball. Where should you move by default?', '[{"id":"a","label":"Move forward and stay balanced for the next shot"},{"id":"b","label":"Retreat behind the fence"},{"id":"c","label":"Freeze at the baseline"},{"id":"d","label":"Turn away"}]'::jsonb, 'a', 'A short ball invites purposeful forward movement and balanced preparation.', '{"player":{"x":50,"y":62},"opponent":{"x":50,"y":14},"ball":{"x":50,"y":58},"recommendedPath":[{"x":50,"y":62},{"x":50,"y":82}],"caption":"Positioning rep 103: you are on the middle while you move in for a short ball."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-114', 'challenger', 'court-position', 2, 'Positioning rep 104: on the middle, you are at net and the opponent is stretched. Where should you move by default?', '[{"id":"a","label":"Back up behind baseline"},{"id":"b","label":"Split step and cover the high-percentage pass"},{"id":"c","label":"Stand at one alley only"},{"id":"d","label":"Watch without moving"}]'::jsonb, 'b', 'At net, split step and cover the likely passing lane or volley.', '{"player":{"x":50,"y":58},"opponent":{"x":50,"y":18},"ball":{"x":50,"y":24},"recommendedPath":[{"x":50,"y":58},{"x":50,"y":82}],"caption":"Positioning rep 104: you are on the middle while you are at net and the opponent is stretched."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-115', 'challenger', 'court-position', 1, 'Positioning rep 105: on the middle, a high deep ball is landing near your baseline. Where should you move by default?', '[{"id":"a","label":"Crowd the bounce"},{"id":"b","label":"Charge forward early"},{"id":"c","label":"Give yourself space behind the bounce"},{"id":"d","label":"Stand in no-man’s-land"}]'::jsonb, 'c', 'High deep balls require space so you can strike in balance.', '{"player":{"x":50,"y":94},"opponent":{"x":50,"y":9},"ball":{"x":50,"y":90},"recommendedPath":[{"x":50,"y":94},{"x":50,"y":82}],"caption":"Positioning rep 105: you are on the middle while a high deep ball is landing near your baseline."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
  ('challenger-116', 'challenger', 'court-position', 3, 'Positioning rep 106: on the middle, the opponent is approaching the net. Where should you move by default?', '[{"id":"a","label":"Hit while falling away"},{"id":"b","label":"Stop recovering"},{"id":"c","label":"Always drop shot"},{"id":"d","label":"Set your feet and prepare pass or lob coverage"}]'::jsonb, 'd', 'Balance gives you time to choose a pass or lob against an approaching player.', '{"player":{"x":50,"y":84},"opponent":{"x":50,"y":32},"ball":{"x":50,"y":78},"recommendedPath":[{"x":50,"y":84},{"x":50,"y":82}],"caption":"Positioning rep 106: you are on the middle while the opponent is approaching the net."}'::jsonb, 'ITF Coaching resources (tactical concepts, paraphrased)', 'https://www.itftennis.com/en/growing-the-game/coaching/', true, true),
