  ('rookie-146', 'rookie', 'rules', 2, 'In friendly set scenario 136, what is the correct rule for two faults?', '[{"id":"a","label":"Third serve"},{"id":"b","label":"The server loses the point"},{"id":"c","label":"Replay"},{"id":"d","label":"Receiver chooses"}]'::jsonb, 'b', 'Two faults on the same point make a double fault, so the server loses the point.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-147', 'rookie', 'rules', 1, 'In friendly set scenario 137, what is the correct rule for serve clips net and lands in?', '[{"id":"a","label":"Server wins point"},{"id":"b","label":"Receiver wins point"},{"id":"c","label":"Replay the serve"},{"id":"d","label":"Replay game"}]'::jsonb, 'c', 'A serve that touches the net and lands in the correct service box is a let and is replayed.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
