  ('rookie-150', 'rookie', 'rules', 3, 'In friendly set scenario 140, what is the correct rule for rally shot stays in net?', '[{"id":"a","label":"Replay"},{"id":"b","label":"The hitter loses the point"},{"id":"c","label":"Ball remains live"},{"id":"d","label":"Opponent loses point"}]'::jsonb, 'b', 'A player loses the point when their shot does not cross the net into the opponent’s court.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-151', 'rookie', 'rules', 1, 'In friendly set scenario 141, what is the correct rule for returning a serve?', '[{"id":"a","label":"Receiver may volley it"},{"id":"b","label":"Server may catch it"},{"id":"c","label":"The receiver must let the serve bounce"},{"id":"d","label":"It must bounce twice"}]'::jsonb, 'c', 'The receiver must allow the serve to bounce before returning it.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
