  ('rookie-57', 'rookie', 'rules', 1, 'In practice set scenario 47, what is the correct rule for doubles service game?', '[{"id":"a","label":"One player serves the whole game"},{"id":"b","label":"Partners switch every point"},{"id":"c","label":"Receiver picks the server"},{"id":"d","label":"Server changes after a fault"}]'::jsonb, 'a', 'In doubles, one player serves for the whole game, then the team order continues in later service games.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-58', 'rookie', 'rules', 2, 'In practice set scenario 48, what is the correct rule for server steps on baseline early?', '[{"id":"a","label":"Let"},{"id":"b","label":"Foot fault"},{"id":"c","label":"Legal serve"},{"id":"d","label":"Receiver hindrance"}]'::jsonb, 'b', 'A server may not touch the baseline or court before striking the serve.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-59', 'rookie', 'rules', 1, 'In practice set scenario 49, what is the correct rule for ball touches player?', '[{"id":"a","label":"Replay"},{"id":"b","label":"Opponent loses point"},{"id":"c","label":"That player loses the point"},{"id":"d","label":"Warning only"}]'::jsonb, 'c', 'A player loses the point if the ball touches them or what they are wearing or carrying.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-60', 'rookie', 'rules', 3, 'In practice set scenario 50, what is the correct rule for deliberate distraction?', '[{"id":"a","label":"All distractions are ignored"},{"id":"b","label":"Always replay"},{"id":"c","label":"Only server can hinder"},{"id":"d","label":"Deliberate hindrance can lose the point"}]'::jsonb, 'd', 'A deliberate hindrance can cause the player creating it to lose the point.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-61', 'rookie', 'rules', 1, 'In league match scenario 51, what is the correct rule for zero points?', '[{"id":"a","label":"Love"},{"id":"b","label":"15"},{"id":"c","label":"30"},{"id":"d","label":"40"}]'::jsonb, 'a', 'Zero points in tennis is called love.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-62', 'rookie', 'rules', 2, 'In league match scenario 52, what is the correct rule for one point?', '[{"id":"a","label":"Love"},{"id":"b","label":"15"},{"id":"c","label":"30"},{"id":"d","label":"40"}]'::jsonb, 'b', 'One point won in a standard game is called 15.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-63', 'rookie', 'rules', 1, 'In league match scenario 53, what is the correct rule for two points?', '[{"id":"a","label":"15"},{"id":"b","label":"40"},{"id":"c","label":"30"},{"id":"d","label":"Advantage"}]'::jsonb, 'c', 'Two points won in a standard game is called 30.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-64', 'rookie', 'rules', 2, 'In league match scenario 54, what is the correct rule for three points?', '[{"id":"a","label":"30"},{"id":"b","label":"45"},{"id":"c","label":"Game"},{"id":"d","label":"40"}]'::jsonb, 'd', 'Three points won in a standard game is called 40.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-65', 'rookie', 'rules', 3, 'In league match scenario 55, what is the correct rule for three points each?', '[{"id":"a","label":"Deuce"},{"id":"b","label":"30-all"},{"id":"c","label":"Advantage"},{"id":"d","label":"Game"}]'::jsonb, 'a', 'When both players have three points, the score is deuce.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-66', 'rookie', 'rules', 2, 'In league match scenario 56, what is the correct rule for one point after deuce?', '[{"id":"a","label":"Deuce"},{"id":"b","label":"Advantage"},{"id":"c","label":"Game"},{"id":"d","label":"Love"}]'::jsonb, 'b', 'The point after deuce gives that player advantage.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-67', 'rookie', 'rules', 1, 'In league match scenario 57, what is the correct rule for advantage is lost?', '[{"id":"a","label":"Game server"},{"id":"b","label":"Game receiver"},{"id":"c","label":"Back to deuce"},{"id":"d","label":"15-all"}]'::jsonb, 'c', 'When the player with advantage loses the next point, the score returns to deuce.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-68', 'rookie', 'rules', 2, 'In league match scenario 58, what is the correct rule for score-calling order?', '[{"id":"a","label":"The receiver’s score is called first"},{"id":"b","label":"The higher score is called first"},{"id":"c","label":"Either order is fine"},{"id":"d","label":"The server’s score is called first"}]'::jsonb, 'd', 'The server’s score is always announced first in a game score.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-69', 'rookie', 'rules', 1, 'In league match scenario 59, what is the correct rule for legal serve target?', '[{"id":"a","label":"In the diagonal service box"},{"id":"b","label":"Anywhere in singles court"},{"id":"c","label":"Straight ahead only"},{"id":"d","label":"Behind the baseline"}]'::jsonb, 'a', 'A serve must land in the service box diagonally opposite the server.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-70', 'rookie', 'rules', 3, 'In league match scenario 60, what is the correct rule for serve misses box?', '[{"id":"a","label":"Let"},{"id":"b","label":"Fault"},{"id":"c","label":"Point server"},{"id":"d","label":"Point receiver"}]'::jsonb, 'b', 'A serve that misses the correct service box is a fault.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-71', 'rookie', 'rules', 1, 'In league match scenario 61, what is the correct rule for two faults?', '[{"id":"a","label":"Third serve"},{"id":"b","label":"Replay"},{"id":"c","label":"The server loses the point"},{"id":"d","label":"Receiver chooses"}]'::jsonb, 'c', 'Two faults on the same point make a double fault, so the server loses the point.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-72', 'rookie', 'rules', 2, 'In league match scenario 62, what is the correct rule for serve clips net and lands in?', '[{"id":"a","label":"Server wins point"},{"id":"b","label":"Receiver wins point"},{"id":"c","label":"Replay game"},{"id":"d","label":"Replay the serve"}]'::jsonb, 'd', 'A serve that touches the net and lands in the correct service box is a let and is replayed.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-73', 'rookie', 'rules', 1, 'In league match scenario 63, what is the correct rule for ball touches line?', '[{"id":"a","label":"In"},{"id":"b","label":"Out"},{"id":"c","label":"Replay"},{"id":"d","label":"Fault"}]'::jsonb, 'a', 'A ball touching any part of the correct line is in.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-74', 'rookie', 'rules', 2, 'In league match scenario 64, what is the correct rule for ball lands fully outside?', '[{"id":"a","label":"In"},{"id":"b","label":"Out"},{"id":"c","label":"Replay"},{"id":"d","label":"Let"}]'::jsonb, 'b', 'A ball landing completely outside the relevant lines is out.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-75', 'rookie', 'rules', 3, 'In league match scenario 65, what is the correct rule for rally shot stays in net?', '[{"id":"a","label":"Replay"},{"id":"b","label":"Ball remains live"},{"id":"c","label":"The hitter loses the point"},{"id":"d","label":"Opponent loses point"}]'::jsonb, 'c', 'A player loses the point when their shot does not cross the net into the opponent’s court.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-76', 'rookie', 'rules', 2, 'In league match scenario 66, what is the correct rule for returning a serve?', '[{"id":"a","label":"Receiver may volley it"},{"id":"b","label":"Server may catch it"},{"id":"c","label":"It must bounce twice"},{"id":"d","label":"The receiver must let the serve bounce"}]'::jsonb, 'd', 'The receiver must allow the serve to bounce before returning it.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-77', 'rookie', 'rules', 1, 'In league match scenario 67, what is the correct rule for serving sides?', '[{"id":"a","label":"Right side first, then alternate"},{"id":"b","label":"Left side first always"},{"id":"c","label":"Any side"},{"id":"d","label":"Middle only"}]'::jsonb, 'a', 'A game starts with service from the right side, then the server alternates sides each point.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-78', 'rookie', 'rules', 2, 'In league match scenario 68, what is the correct rule for change of ends?', '[{"id":"a","label":"After every point"},{"id":"b","label":"After odd-numbered games"},{"id":"c","label":"Only after each set"},{"id":"d","label":"After even-numbered games"}]'::jsonb, 'b', 'Players normally change ends after odd-numbered games.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-79', 'rookie', 'rules', 1, 'In league match scenario 69, what is the correct rule for set tiebreak timing?', '[{"id":"a","label":"At 3-all"},{"id":"b","label":"Every game"},{"id":"c","label":"At the agreed score, often 6-all"},{"id":"d","label":"After the set ends"}]'::jsonb, 'c', 'Many formats use a tiebreak at an agreed score such as 6-all.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
