  ('rookie-96', 'rookie', 'rules', 2, 'In junior drill scenario 86, what is the correct rule for two faults?', '[{"id":"a","label":"Third serve"},{"id":"b","label":"Replay"},{"id":"c","label":"Receiver chooses"},{"id":"d","label":"The server loses the point"}]'::jsonb, 'd', 'Two faults on the same point make a double fault, so the server loses the point.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-97', 'rookie', 'rules', 1, 'In junior drill scenario 87, what is the correct rule for serve clips net and lands in?', '[{"id":"a","label":"Replay the serve"},{"id":"b","label":"Server wins point"},{"id":"c","label":"Receiver wins point"},{"id":"d","label":"Replay game"}]'::jsonb, 'a', 'A serve that touches the net and lands in the correct service box is a let and is replayed.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-98', 'rookie', 'rules', 2, 'In junior drill scenario 88, what is the correct rule for ball touches line?', '[{"id":"a","label":"Out"},{"id":"b","label":"In"},{"id":"c","label":"Replay"},{"id":"d","label":"Fault"}]'::jsonb, 'b', 'A ball touching any part of the correct line is in.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('rookie-99', 'rookie', 'rules', 1, 'In junior drill scenario 89, what is the correct rule for ball lands fully outside?', '[{"id":"a","label":"In"},{"id":"b","label":"Replay"},{"id":"c","label":"Out"},{"id":"d","label":"Let"}]'::jsonb, 'c', 'A ball landing completely outside the relevant lines is out.', null, 'ITF Rules of Tennis (2026)', 'https://www.itftennis.com/en/about-us/governance/rules-and-regulations/', true, false),
  ('strategist-01', 'strategist', 'shot-choice', 2, 'You are balanced in the middle of your court with a comfortable, mid-height ball. Your opponent has been pulled wide, outside the far sideline on the left side of the diagram. Which shot is the best default?', '[{"id":"a","label":"Back to the same corner to wrong-foot them"},{"id":"b","label":"A drop shot just over the net"},{"id":"c","label":"A firm shot into the open court on the right, aimed well inside the sideline"},{"id":"d","label":"A high lob over your opponent"}]'::jsonb, 'c', 'The open court makes your opponent run the farthest, and aiming well inside the line keeps your margin. Going behind them can wrong-foot a fast recoverer, but against a player still stranded wide the open court is the higher-percentage choice.', '{"player":{"x":50,"y":80},"opponent":{"x":10,"y":8},"ball":{"x":50,"y":78},"caption":"You are balanced in the middle of your half, between baseline and service line. Your opponent is far out wide beyond the far left sideline, near their baseline, leaving the right side of their court open."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-02', 'strategist', 'shot-choice', 2, 'Your opponent has drifted far behind their baseline in the middle. You are inside your baseline on a short, slow, mid-height ball, and conditions are calm. Which shot is the best choice?', '[{"id":"a","label":"A drop shot that bounces soon after crossing the net"},{"id":"b","label":"A hard, flat shot straight at your opponent"},{"id":"c","label":"A high lob deep to their baseline"},{"id":"d","label":"A slow, deep rally ball back to the middle"}]'::jsonb, 'a', 'Your opponent has the longest possible run to the net, and from inside the court your drop shot only travels a short distance. A deep approach shot is also reasonable, but the drop shot best exploits their position.', '{"player":{"x":55,"y":72},"opponent":{"x":50,"y":2},"caption":"You are just behind your service line, near the middle of your half. Your opponent is far behind the far baseline, in the middle."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-03', 'strategist', 'shot-choice', 2, 'A deep, heavy ball has pushed you far behind your baseline near the left corner. Your opponent is on their baseline. Which reply is the safest default?', '[{"id":"a","label":"A drop shot from where you are"},{"id":"b","label":"A flat, low winner down the line"},{"id":"c","label":"A sharp, short angle crosscourt"},{"id":"d","label":"A high, deep crosscourt ball with plenty of net clearance"}]'::jsonb, 'd', 'From deep and off balance, a high crosscourt ball gives you the most margin and time to recover. A drop shot from far back travels too long and usually sits up for your opponent.', '{"player":{"x":22,"y":98},"opponent":{"x":50,"y":5},"caption":"You are far behind your baseline near the left corner. Your opponent is on the far baseline in the middle."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-04', 'strategist', 'shot-choice', 2, 'In a neutral rally with both players on the baseline, which target gives the best balance of pressure and safety?', '[{"id":"a","label":"Right on the sidelines and baseline, for maximum pressure"},{"id":"b","label":"Deep, a metre or two inside the lines, with comfortable net clearance"},{"id":"c","label":"Just over the net, as low as possible"},{"id":"d","label":"Into the service boxes"}]'::jsonb, 'b', 'Aiming a little inside the lines and well over the net leaves room for small errors while still keeping your opponent deep. Line-hugging targets win some points outright but cost more errors over a match.', '{"player":{"x":50,"y":96},"opponent":{"x":50,"y":4},"caption":"Both players are rallying from behind their baselines, in the middle of the court. Neither player is under pressure."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-05', 'strategist', 'shot-choice', 2, 'You get a short, mid-height ball on the right side of your court, just inside the service line. Your opponent is behind their baseline in the middle. You decide to come to the net. Where should you hit the approach shot?', '[{"id":"a","label":"Crosscourt to the far left corner"},{"id":"b","label":"Short and soft to the middle"},{"id":"c","label":"Deep down the line toward the far right corner, then follow it in"},{"id":"d","label":"A lob over your opponent"}]'::jsonb, 'c', 'A down-the-line approach reaches your opponent sooner and lets you follow the ball to cover their likely passing lanes. A crosscourt approach can work, but it leaves the down-the-line pass open behind you.', '{"player":{"x":72,"y":66},"opponent":{"x":50,"y":4},"ball":{"x":72,"y":64},"recommendedPath":[{"x":72,"y":64},{"x":78,"y":10}],"caption":"You are on the right side of your half, just inside your service line, with the ball in front of you. Your opponent is behind the far baseline in the middle."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-06', 'strategist', 'shot-choice', 2, 'Your deep approach has pushed your opponent into the far right corner, and they float a slow, high reply toward the middle. You are balanced at the net. Which volley is best?', '[{"id":"a","label":"A firm volley into the open court on the far left, away from your opponent"},{"id":"b","label":"A volley back to your opponent''s corner"},{"id":"c","label":"Let it bounce and rally from the baseline"},{"id":"d","label":"A lob volley over your opponent"}]'::jsonb, 'a', 'A floating reply gives you time to place the volley where your opponent is not. Volleying back to their corner gives them a second chance to pass you.', '{"player":{"x":62,"y":60},"opponent":{"x":80,"y":4},"ball":{"x":58,"y":58},"caption":"You are at the net, a little right of center. A slow, high ball is floating toward you. Your opponent is deep in the far right corner, leaving the far left side open."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-07', 'strategist', 'shot-choice', 2, 'Your opponent is close to the net in the middle. You are stretched wide behind your baseline near the right sideline, hitting on the run. Which shot is the best default?', '[{"id":"a","label":"A hard, flat passing shot down the line"},{"id":"b","label":"A high, deep defensive lob over your opponent"},{"id":"c","label":"A soft drop shot"},{"id":"d","label":"A hard shot straight at the net player"}]'::jsonb, 'b', 'When you are stretched, a high, deep lob buys time to recover and forces the net player to turn and chase. A passing shot is possible when you are balanced, but on the run it is a low-percentage choice.', '{"player":{"x":93,"y":97},"opponent":{"x":50,"y":40},"caption":"You are outside the right sideline behind your baseline, running wide. Your opponent is close to the net in the middle of the far half."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-08', 'strategist', 'shot-choice', 3, 'You have been rallying crosscourt from the left side of your court, and your opponent is waiting in the far right corner. Now you get a short, comfortable ball inside your baseline. What is a sensible choice?', '[{"id":"a","label":"Keep rallying crosscourt at the same pace"},{"id":"b","label":"A high defensive lob"},{"id":"c","label":"A sharp short angle into the area your opponent is covering"},{"id":"d","label":"Change direction down the line, toward the open far left corner"}]'::jsonb, 'd', 'Changing direction down the line works best on a short, comfortable ball, because the line shot crosses the higher part of the net and has less court to land in. Here you have that ball and an open court, so it is a good moment to switch; on a deep or difficult ball, staying crosscourt would be safer.', '{"player":{"x":28,"y":86},"opponent":{"x":72,"y":6},"ball":{"x":28,"y":84},"caption":"You are inside your baseline on the left side of your half, with a short ball in front of you. Your opponent is behind the far baseline on the right side of the diagram, leaving the far left corner open."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-09', 'strategist', 'shot-choice', 3, 'Your opponent has come forward and is standing near their service line. You are balanced just behind your baseline with a low ball below net height. Which shot is the best default?', '[{"id":"a","label":"A high, deep lob"},{"id":"b","label":"A hard, rising shot aimed at their chest"},{"id":"c","label":"A dipping shot that drops low at their feet or past them"},{"id":"d","label":"A drop shot"}]'::jsonb, 'c', 'An opponent near the service line is vulnerable to a ball that dips at their feet, forcing an upward volley. A lob is a reasonable alternative, especially if they move closer to the net.', '{"player":{"x":50,"y":93},"opponent":{"x":50,"y":30},"caption":"You are just behind your baseline in the middle. Your opponent has moved forward and is standing near the far service line, in the middle."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-10', 'strategist', 'shot-choice', 2, 'Assume you know your opponent''s backhand is clearly weaker than their forehand, and the rally is neutral. Which plan best builds the point?', '[{"id":"a","label":"Keep hitting deep, steady balls to the backhand until you get a short ball to attack"},{"id":"b","label":"Go for an outright winner on the first ball"},{"id":"c","label":"Hit everything to the forehand to tire them out"},{"id":"d","label":"Hit every shot to a new corner as hard as possible"}]'::jsonb, 'a', 'Steady pressure on the weaker side tends to draw a short or defensive reply that you can then attack. An occasional ball to the forehand still helps open the court, but the backhand is the main target.', null, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-100', 'strategist', 'shot-choice', 3, 'Tactical rep 90: from the near net, opponent over-covers a corner. Which shot choice is the best default?', '[{"id":"a","label":"Always hit wider"},{"id":"b","label":"Float short"},{"id":"c","label":"Ignore movement"},{"id":"d","label":"Play behind them or through the open middle"}]'::jsonb, 'd', 'Open space can appear behind an over-moving opponent or through the middle.', '{"player":{"x":45,"y":68},"opponent":{"x":58,"y":10},"ball":{"x":47,"y":66},"recommendedPath":[{"x":45,"y":68},{"x":50,"y":78}],"caption":"Tactical rep 90: you are on the near net and opponent over-covers a corner."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-101', 'strategist', 'shot-choice', 1, 'Tactical rep 91: from the behind baseline, opponent is far behind the baseline. Which shot choice is the best default?', '[{"id":"a","label":"Use a controlled shorter ball or drop shot if balanced"},{"id":"b","label":"Feed slow to middle"},{"id":"c","label":"Aim only at back fence"},{"id":"d","label":"Stop and wait"}]'::jsonb, 'a', 'A deep opponent has more forward court to cover, so a controlled short ball can be effective.', '{"player":{"x":52,"y":66},"opponent":{"x":50,"y":4},"ball":{"x":52,"y":62},"recommendedPath":[{"x":52,"y":66},{"x":50,"y":78}],"caption":"Tactical rep 91: you are on the behind baseline and opponent is far behind the baseline."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-102', 'strategist', 'shot-choice', 2, 'Tactical rep 92: from the behind baseline, you are stretched wide and late. Which shot choice is the best default?', '[{"id":"a","label":"Low flat line winner"},{"id":"b","label":"Send a higher crosscourt ball with margin"},{"id":"c","label":"Drop shot from full stretch"},{"id":"d","label":"Aim at the fence"}]'::jsonb, 'b', 'When stretched, height and crosscourt margin buy recovery time.', '{"player":{"x":52,"y":82},"opponent":{"x":50,"y":8},"ball":{"x":52,"y":76},"recommendedPath":[{"x":52,"y":82},{"x":50,"y":78}],"caption":"Tactical rep 92: you are on the behind baseline and you are stretched wide and late."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-103', 'strategist', 'shot-choice', 1, 'Tactical rep 93: from the behind baseline, you receive a short sitter. Which shot choice is the best default?', '[{"id":"a","label":"Retreat and moonball"},{"id":"b","label":"Push short to middle"},{"id":"c","label":"Approach deep to a corner and follow forward"},{"id":"d","label":"Let it drop twice"}]'::jsonb, 'c', 'A short sitter is an attacking chance; deep placement supports moving forward.', '{"player":{"x":52,"y":58},"opponent":{"x":50,"y":10},"ball":{"x":52,"y":55},"recommendedPath":[{"x":52,"y":58},{"x":50,"y":78}],"caption":"Tactical rep 93: you are on the behind baseline and you receive a short sitter."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-104', 'strategist', 'shot-choice', 3, 'Tactical rep 94: from the behind baseline, opponent has a weak second serve. Which shot choice is the best default?', '[{"id":"a","label":"Stand far back"},{"id":"b","label":"Swing blindly"},{"id":"c","label":"Concede the point"},{"id":"d","label":"Step in and return with controlled depth"}]'::jsonb, 'd', 'A weak second serve is a chance to take time away with controlled depth.', '{"player":{"x":52,"y":80},"opponent":{"x":50,"y":4},"ball":{"x":52,"y":68},"recommendedPath":[{"x":52,"y":80},{"x":50,"y":78}],"caption":"Tactical rep 94: you are on the behind baseline and opponent has a weak second serve."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-105', 'strategist', 'shot-choice', 1, 'Tactical rep 95: from the behind baseline, opponent is moving forward to net. Which shot choice is the best default?', '[{"id":"a","label":"Hit a dipping pass or lob based on their position"},{"id":"b","label":"Hit to comfortable volley"},{"id":"c","label":"Stop the rally"},{"id":"d","label":"Only drop shot"}]'::jsonb, 'a', 'Make an approaching player volley up or move backward.', '{"player":{"x":52,"y":84},"opponent":{"x":50,"y":32},"ball":{"x":52,"y":78},"recommendedPath":[{"x":52,"y":84},{"x":50,"y":78}],"caption":"Tactical rep 95: you are on the behind baseline and opponent is moving forward to net."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-106', 'strategist', 'shot-choice', 2, 'Tactical rep 96: from the behind baseline, you have pushed the opponent wide. Which shot choice is the best default?', '[{"id":"a","label":"Hit back to middle only"},{"id":"b","label":"Attack the open court or wrong-foot an early recovery"},{"id":"c","label":"Aim outside sideline"},{"id":"d","label":"Stop moving"}]'::jsonb, 'b', 'After pulling an opponent wide, use the open court or punish over-recovery.', '{"player":{"x":52,"y":70},"opponent":{"x":50,"y":12},"ball":{"x":52,"y":68},"recommendedPath":[{"x":52,"y":70},{"x":50,"y":78}],"caption":"Tactical rep 96: you are on the behind baseline and you have pushed the opponent wide."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-107', 'strategist', 'shot-choice', 1, 'Tactical rep 97: from the behind baseline, both players are central in a neutral rally. Which shot choice is the best default?', '[{"id":"a","label":"Aim for lines only"},{"id":"b","label":"Rush net without approach"},{"id":"c","label":"Build with depth and margin before changing direction"},{"id":"d","label":"Change direction off every hard ball"}]'::jsonb, 'c', 'Neutral rallies reward depth and margin before riskier changes of direction.', '{"player":{"x":52,"y":86},"opponent":{"x":50,"y":9},"ball":{"x":52,"y":76},"recommendedPath":[{"x":52,"y":86},{"x":50,"y":78}],"caption":"Tactical rep 97: you are on the behind baseline and both players are central in a neutral rally."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-108', 'strategist', 'shot-choice', 3, 'Tactical rep 98: from the behind baseline, opponent attacks your backhand repeatedly. Which shot choice is the best default?', '[{"id":"a","label":"Slap every ball down line"},{"id":"b","label":"Move away early"},{"id":"c","label":"Give up baseline"},{"id":"d","label":"Use height, depth, or crosscourt shape to reset"}]'::jsonb, 'd', 'A higher deeper reply can reset pressure and reduce errors.', '{"player":{"x":52,"y":88},"opponent":{"x":50,"y":9},"ball":{"x":52,"y":82},"recommendedPath":[{"x":52,"y":88},{"x":50,"y":78}],"caption":"Tactical rep 98: you are on the behind baseline and opponent attacks your backhand repeatedly."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-109', 'strategist', 'shot-choice', 1, 'Tactical rep 99: from the behind baseline, you are ahead but not balanced to finish. Which shot choice is the best default?', '[{"id":"a","label":"Keep pressure with a high-percentage target"},{"id":"b","label":"Force a poor-balance winner"},{"id":"c","label":"Try a trick shot"},{"id":"d","label":"Stop recovering"}]'::jsonb, 'a', 'Control does not require a reckless finish; pressure can create the next easier ball.', '{"player":{"x":52,"y":64},"opponent":{"x":50,"y":16},"ball":{"x":52,"y":61},"recommendedPath":[{"x":52,"y":64},{"x":50,"y":78}],"caption":"Tactical rep 99: you are on the behind baseline and you are ahead but not balanced to finish."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
  ('strategist-11', 'strategist', 'shot-choice', 1, 'Tactical rep 1: from the middle, opponent is far behind the baseline. Which shot choice is the best default?', '[{"id":"a","label":"Feed slow to middle"},{"id":"b","label":"Aim only at back fence"},{"id":"c","label":"Use a controlled shorter ball or drop shot if balanced"},{"id":"d","label":"Stop and wait"}]'::jsonb, 'c', 'A deep opponent has more forward court to cover, so a controlled short ball can be effective.', '{"player":{"x":50,"y":66},"opponent":{"x":50,"y":4},"ball":{"x":50,"y":62},"recommendedPath":[{"x":50,"y":66},{"x":50,"y":78}],"caption":"Tactical rep 1: you are on the middle and opponent is far behind the baseline."}'::jsonb, 'USTA Improve: tennis tips and match strategies (paraphrased)', 'https://www.usta.com/en/home/improve.html', true, true),
